mapper.select:
SELECT * FROM owner


        AND id =#{id}


        AND username LIKE CONCAT('%', #{username}, '%')


        AND tel LIKE CONCAT('%', #{tel}, '%')


        AND sex = #{sex}


        AND identity LIKE CONCAT('%', #{identity}, '%')


        AND house_id = #{houseId}


        AND remarks LIKE CONCAT('%', #{remarks}, '%')


        AND password = #{password}


        AND isDelete = #{isDelete}


        AND deltime = #{deltime}
